
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_vsk_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_vsk", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.391450542106720e+01, 9.026051527416466e+01, 8.526450784321288e+01, 7.858319208060294e+01, 6.992691001717802e+01, 5.920823106934985e+01, 4.676336163089932e+01, 3.357415756077458e+01, 2.129413669695883e+01, 1.181828236603278e+01, 6.037494398105674e+00, 2.544652433160391e+00, 1.906477495470731e+00, 1.264251155709755e+00, 6.524278540831823e-01, 3.542212464622835e-01, 5.053134914406844e-01, 6.477222245415964e-01, 6.037033403471660e-01, 5.743518985017524e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


